// Croatian (hr-HR) UI copy.
//
// COMPLETE: every key EN carries has a Croatian string, so nothing on this
// locale falls through to the English fallback any more. That is what lets it
// be typed `LocaleMessages` rather than `PartialLocaleMessages` and drop out
// of `PARTIAL_LOCALES` in lib/i18n: a key added to EN without one here is now
// a compile error rather than a silently English screen.
//
// Register: formal "vi" throughout, matching how a Croatian business expects
// to be addressed by a tool it pays for, and how a couple expects to be
// addressed by one they are paying. Placeholders like {name} / {count} are
// part of the contract with `interpolate()` and must survive verbatim.

