    proc_directory_title: "Unosi u katalogu za tvrtke uvrštene bez računa",
    proc_directory_data:
      "Obrađivani podaci: naziv tvrtke, kategorija usluge, mjesto i adresa, mrežna stranica, poslovna adresa e-pošte i telefonski broj koje je tvrtka sama objavila, procijenjeni raspon cijene i kapaciteta, kratak činjeničan sažetak koji smo mi napisali te slika koju vlastita mrežna stranica tvrtke koristi kao pregled za dijeljenje.",
    proc_directory_source:
      "Izvor podataka: vlastita javna mrežna stranica i profil na društvenim mrežama tvrtke, javni registri trgovačkih društava i obrta, javni kartografski i adresni podaci, vlastita prijava tvrtke ili preporuka korisnika. Iza prijave ne prikupljamo ništa.",
    proc_directory_purpose:
      "Svrha: održavanje potpunog i upotrebljivog kataloga dobavljača za vjenčanja namijenjenog parovima te omogućavanje tvrtki da vlastiti profil bez naknade preuzme i sama uređuje.",
    proc_directory_basis:
      "Pravna osnova: ondje gdje je unos podatak pravne osobe, obrada je izvan područja primjene GDPR-a (vidjeti uvodnu izjavu (14) i § 10. st. 2. Zakona V iz 2006.); ondje gdje se može povezati s fizičkom osobom, čl. 6. st. 1. t. (f) GDPR-a, legitimni interesi voditelja obrade i parova, potkrijepljeni dokumentiranom procjenom ravnoteže interesa.",
    proc_directory_retention:
      "Rok čuvanja: dok se unos pojavljuje u katalogu. Kod osnovanog prigovora ili zahtjeva za brisanje brišemo ga odmah nakon ocjene; sam zahtjev i naš odgovor čuvamo 5 godina radi pouzdanosti i ostvarivanja pravnih zahtjeva.",
    proc_outreach_title: "Kataloške obavijesti poslane tvrtkama",
    proc_outreach_data:
      "Obrađivani podaci: poslovna adresa e-pošte koju je tvrtka objavila, oznaka unosa kojemu pripada, vrijeme slanja, otvaranja i klika te činjenica i vrijeme eventualne odjave.",
    proc_outreach_purpose:
      "Svrha: obavijestiti tvrtku da je u katalogu objavljen unos o njoj i ponuditi joj priliku da unos bez naknade preuzme, da ga dade ispraviti ili da mu prigovori. To je ujedno i praktično sredstvo za informiranje koje traži čl. 14. GDPR-a.",
    proc_outreach_basis:
      "Pravna osnova: čl. 6. st. 1. t. (f) GDPR-a. Poruka ide na poslovnu adresu i tiče se vlastitog unosa primatelja, pa je ne tretiramo kao izravni marketing upućen fizičkoj osobi koji ovisi o privoli u smislu § 6. mađarskog Zakona XLVIII iz 2008. o gospodarskom oglašavanju. Ondje gdje poruka sadrži i ponudu koja se odnosi na našu vlastitu (kasnije naplatnu) uslugu, šaljemo je isključivo na poslovne adrese, a svaka poruka nosi odjavu u jednom kliku, i u podnožju i u zaglavlju List-Unsubscribe prema RFC 8058.",
    proc_outreach_retention:
      "Rok čuvanja i ograničenja: najviše jedan podsjetnik po kampanji. Nakon odjave ili pisanog zahtjeva toj adresi više nikada ne šaljemo poruke iz kampanja; zabrana se veže uz adresu, trajna je i vrijedi za sve kampanje. Zapisnik slanja čuvamo onoliko dugo koliko nam je potreban za dokazivanje usklađenosti te za ostvarivanje ili obranu pravnih zahtjeva, a najviše 5 godina od zatvaranja kampanje. Zapis o zabrani čuvamo neograničeno jer upravo taj zapis sprječava svaki daljnji kontakt.",
    proc_reviews_title: "Recenzije i javna pitanja",
    proc_reviews_data:
      "Obrađivani podaci: broj zvjezdica, tekst recenzije, odabrane oznake, neobavezno navedeni plaćeni iznos, prikazano ime osobe koja ocjenjuje, adresa e-pošte s njezina računa (nikada se ne objavljuje) i vrijeme recenzije.",
    proc_reviews_purpose:
      "Svrha: objava iskustava parova u katalogu kako bi drugi parovi mogli donositi informirane odluke te filtriranje neistinitih ili nezakonitih recenzija.",
    proc_reviews_basis:
      "Pravna osnova: za objavu čl. 6. st. 1. t. (a) GDPR-a, dobrovoljna privola osobe koja ocjenjuje; za moderiranje i filtriranje zlouporaba čl. 6. st. 1. t. (f), legitimni interes.",
    proc_reviews_retention:
      "Rok čuvanja: do povlačenja recenzije ili brisanja unosa. Autor recenzije svoju recenziju može urediti ili izbrisati u svakom trenutku.",
    vendor_transfer_title: "Prijenos podataka pružateljima usluga za vjenčanja",
    vendor_transfer_body:
      "Ako iz kataloga dobavljača pokrenete kontakt s određenim partnerom (npr. pošaljete zahtjev za ponudu), voditelj obrade može kontaktne podatke koje ste naveli (ime, adresu e-pošte, telefonski broj) podijeliti s tim partnerom radi ispunjenja vašeg zahtjeva. Pravna je osnova čl. 6. st. 1. t. (b) GDPR-a, priprema ugovora na zahtjev ispitanika. Prenosi se samo najmanja količina podataka nužna za ispunjenje.",
