    acceptable_use_prohibited_spam:
      "Neželjena pošta, neželjeni marketing, kupnja ili prodaja popisa gostiju drugim parovima.",
    ugc_title: "Sadržaj koji stvaraju korisnici",
    ugc_license_body:
      "Kad na Weddly učitate ili pošaljete sadržaj (npr. unos dobavljača iz zajednice, URL za moodboard, povratnu informaciju, stavku popisa gostiju), zadržavate sva prava koja ste na tom sadržaju već imali. Za rad usluge potrebna nam je neisključiva, besplatna, svjetska licencija s pravom podlicenciranja za pohranu, prikaz, tehničku obradu (promjena veličine, ponovno kodiranje) i korištenje sadržaja unutar usluge. Licencija automatski prestaje kad sadržaj izbrišete, osim ako zakonska obveza (npr. revizijski zapisnik) ili redovite sigurnosne kopije zahtijevaju kratkotrajno čuvanje.",
    ugc_warranty_body:
      "Jamčite da je sve što pošaljete (a) vaše ili da imate dopuštenje za objavu, (b) da ne krši prava trećih osoba (autorsko pravo, žig, privatnost, poslovnu tajnu) i (c) da je u skladu s gore navedenim pravilima prihvatljivog korištenja. Ako se pokaže da nešto od toga ne stoji, sadržaj možemo ukloniti, a kod teških ili ponovljenih kršenja suspendirati ili izbrisati vaš račun.",
    dsa_title: "Prijava i postupanje (EU Digital Services Act)",
    dsa_body:
      "Uredba (EU) 2022/2065 (DSA) obvezuje svakog pružatelja usluga smještaja sadržaja da omogući jednostavan mehanizam za prijavu nezakonitog sadržaja. Ako smatrate da je sadržaj objavljen na Weddlyju (npr. unos dobavljača iz zajednice) nezakonit, pišite na dsa@weddly.xyz ili, ako ta adresa još nije aktivna, na hello@tryweddly.com / andor.csikasz@gmail.com, i navedite: (1) URL ili drugu nedvojbenu oznaku gdje se sadržaj nalazi; (2) zašto smatrate da je nezakonit; (3) ime i e-adresu prijavitelja; (4) izjavu u dobroj vjeri da je prijava točna. Svaku prijavu razmatramo bez nepotrebnog odgađanja i, kad je opravdano, uklanjamo sadržaj ili onemogućujemo pristup njemu; o odluci i njezinim razlozima obavještavamo i prijavitelja i osobu koja je sadržaj objavila. Interne pritužbe na naše odluke možete poslati na istu adresu.",
    dsa_contact:
      "Jedinstvena kontaktna točka (Single Point of Contact) za tijela i korisnike prema čl. 11. i 12. DSA-a: Andor Csíkász, andor.csikasz@gmail.com. Jezici: mađarski i engleski.",
    directory_title: "Katalog dobavljača",
    directory_body:
      "Katalog dobavljača tijekom otvorene bete besplatno je dostupan za pregledavanje. Ne smijete ga strojno preuzimati (scraping), preprodavati ni ponovno objavljivati, riječ je o uređenoj zbirci zaštićenoj autorskim pravom. Nakon završetka bete uvest ćemo za dobavljače model naplate (pretplata i/ili istaknuto mjesto); pojedinosti su uređene Uvjetima pretplate za dobavljače (ÁSZF), koji su na snazi. Tijekom bete naknade nisu aktivne; prije nego što bilo koja naknada stupi na snagu, svaki će dobavljač najmanje 30 dana ranije primiti zasebnu e-poruku s konačnim cjenikom.",
    directory_listing_policy_title: "Kako dobavljač dospijeva u katalog",
    directory_listing_policy_body:
      "Katalog je uređeni imenik. Unos nastaje na jedan od tri načina: mi ga dodajemo na temelju javno dostupnih, činjeničnih poslovnih podataka, preporuči ga netko od naših korisnika ili ga dobavljač sam prijavi. Sam unos ne znači partnerstvo, preporuku ni ugovor i ne stvara obvezu plaćanja: tvrtka koja nije preuzela svoj profil ne duguje nam ništa. Dobavljači koji su se registrirali i sami vode svoj profil nose oznaku „Provjereno”; ostali je nemaju. Prema mađarskom i EU pravu, neutralno prikazivanje činjeničnih poslovnih podataka u pravilu nije uvjetovano prethodnom privolom tvrtke (uvodna izjava (14) GDPR-a; čl. 10. st. 2. Zakona V. iz 2006. o javnosti trgovačkih društava; čl. 1. st. 3. Zakona LXXVI. iz 1999. o autorskom pravu; čl. 15. st. 1. t. c) Zakona XI. iz 1997. o žigovima). Točna pravna osnova, procjena ravnoteže interesa i postupak prigovora opisani su u poglavlju „Tvrtke koje se u katalogu pojavljuju bez računa” Pravila privatnosti. Ispravak, besplatno preuzimanje profila, trajno onemogućavanje svakog kontakta ili brisanje unosa možete zatražiti na hello@tryweddly.com; obrazložen odgovor dajemo bez nepotrebnog odgađanja, a u svakom slučaju u roku od 30 dana.",
    reviews_title: "Recenzije",
    reviews_body:
      "Recenziju može ostaviti svatko tko ima potvrđenu e-adresu, jednu po dobavljaču. Recenzije ne naručujemo, ne plaćamo ih i ne filtriramo ih po broju zvjezdica: nepovoljna se recenzija prikazuje jednako kao i povoljna. Oznaka „Provjereno” na recenziji znači da je recenzent tog dobavljača zabilježio i u vlastitom planiranju vjenčanja (kao stavku u proračunu ili kao odabranog dobavljača), dakle da je dokazivo bio u kontaktu s njim; izostanak oznake ne znači da je recenzija neistinita, nego samo da takav dokaz nemamo. Ne tvrdimo, niti možemo tvrditi, da svaka recenzija dolazi od potvrđenog klijenta. Recenzija može stići i dobavljaču koji nije preuzeo svoj profil; nakon preuzimanja dobiva javno pravo na odgovor. Neistinite, uvredljive ili nezakonite recenzije uklanjamo po prijavi (vidjeti odjeljak Prijava i postupanje), ali zakonitu recenziju, koliko god bila nepovoljna, na zahtjev ne uklanjamo.",
    liability_title: "Ograničenje odgovornosti",
    liability_body:
      "Weddly se tijekom bete pruža „takav kakav jest” („as is”), besplatno, bez ikakvog izričitog ili prešutnog jamstva (osobito: prikladnost za određenu svrhu, neprekinut rad, rad bez pogrešaka). Odgovornost koju prema mađarskom pravu nije moguće isključiti (namjera, gruba nepažnja, šteta na životu, tjelesnom integritetu ili zdravlju) ne ograničavamo. Za sve druge vrste štete, uključujući neizravnu i posljedičnu štetu te izmaklu dobit, naša je odgovornost ograničena na najuži opseg dopušten mađarskim pravom. Vaša zakonska prava kao potrošača (npr. prava iz jamstva) ovo ograničenje ne dira.",
    termination_title: "Prestanak odnosa",
    termination_body:
      "Račun možete izbrisati u svakom trenutku na stranici Profil; radni prostor trajno se briše nakon roka od 30 dana (vidjeti Pravila privatnosti). Račun možemo suspendirati ili ugasiti ako bitno krši gore navedena pravila prihvatljivog korištenja ili ako se koristi nezakonito odnosno na način koji ugrožava druge korisnike. Razlog vam javljamo e-poštom i, osim ako to sprječava zakonska ili regulatorna obveza, dajemo vam razuman rok da izvezete svoje podatke.",
    changes_title: "Izmjene ovih uvjeta",
    changes_body:
      "Ove uvjete povremeno ažuriramo. Manje jezične ispravke unosimo bez najave. Kod bitnih promjena (nova naknada, novi izvršitelj obrade, sužavanje naših obveza) javljamo vam e-poštom najmanje 14 dana prije stupanja na snagu i tražimo da ažurirane uvjete prihvatite u aplikaciji, bez prihvaćanja dijelovi usluge neće ostati dostupni. Kad otvorena beta završi, svi beta korisnici primit će zasebnu e-poruku o sveobuhvatnoj novoj verziji.",
    law_title: "Mjerodavno pravo",
    law_body:
      "Na ove se uvjete primjenjuju mađarsko pravo i primjenjiva pravila EU-a o zaštiti podataka i potrošača, osobito GDPR i DSA. Spor najprije pokušavamo riješiti e-poštom. Obvezna prava i nadležnosti potrošača prema mjestu uobičajenog boravišta ostaju nepromijenjeni.",
    contact_title: "Pitanja?",
    contact_body: "Pišite na hello@tryweddly.com ili andor.csikasz@gmail.com.",
    en_section_label: "English",
