    budget_p1_body:
      "Upišite planirani iznos po kategoriji i bilježite plaćanja kako stižu. Razlika se osvježava uživo pa prekoračenje uočite rano.",
    budget_p2_title: "Kategorije",
    budget_p2_body:
      "Lokacija, catering, fotografija: svaki je trošak vezan uz kategoriju. Koristite zadane ili dodajte svoje.",
    budget_p3_title: "Trošak po gostu",
    budget_p3_body:
      "Trošak po gostu automatski se izračunava iz stvarnih troškova i potvrđenog broja gostiju, korisno za određivanje konačne granice proračuna.",
    vendors_title: "Dobavljači",
    vendors_body:
      "Pronađite dobavljače po kategoriji i gradu, vodite ugovore, planove plaćanja i kontakte.",
    vendors_p1_title: "Pretraga i uži izbor",
    vendors_p1_body:
      "Pregledavajte provjerene dobavljače po kategoriji i gradu. Spremite favorite na uži izbor i usporedite ih jedan uz drugoga.",
    vendors_p2_title: "Ugovori i kontakti",
    vendors_p2_body:
      "Zabilježite potpisan ugovor, osobu za kontakt i bilješke za svakog rezerviranog dobavljača, sve na jednom mjestu.",
    vendors_p3_title: "Plan plaćanja",
    vendors_p3_body:
      "Pratite predujmove i završne uplate s rokovima po dobavljaču. Proračun te iznose preuzima automatski.",
    planning_title: "Planiranje",
    planning_body:
      "Zadaci, ideje i velike odluke na jednom mjestu, uz vremenski plan u Ganttovu stilu za rokove.",
    planning_p1_title: "Zadaci i popisi",
    planning_p1_body:
      "Dodajte zadatke s rokovima i dodijelite ih sebi ili partneru. Filtrirajte po statusu da vidite što je još otvoreno.",
    planning_p2_title: "Odluke",
    planning_p2_body:
      "131 odabrana odluka o vjenčanju, stil lokacije, pisanje zavjeta, rezanje torte, u obliku vođenog špila da ništa ne promakne.",
